import React from 'react';
import { View } from 'react-native';

import { Cards } from '../../components/Cards';
import { styles } from './styles';

import { useContexState } from '../../hooks/context';

interface ListItemProps {
    data: {
        firstCard: number,
        id: string
    };
    list?: {
        [key: string]: [{
            id: number;
            name: string;
            phone: string;
            price: number;
        }]
    };
};

export function ListItem(listItemProps: ListItemProps) {
    const { setIsMountedApi, isMountedApi } = useContexState();
    return (isMountedApi ? (

        <View style={styles.listItem}>

            <Cards {...{ listItemProps }} position={0} />
            <Cards {...{ listItemProps }} position={1} />
            <Cards {...{ listItemProps }} position={2} />
            <Cards {...{ listItemProps }} position={3} />
            <Cards {...{ listItemProps }} position={4} />
            <Cards {...{ listItemProps }} position={5} />
        </View>) : <View />
    );
};
